#import "KARPASwiftInspector.h"
NSDictionary *KARPAInspectSwiftImages(NSArray<NSDictionary *> *images){NSMutableArray *found=[NSMutableArray array];for(NSDictionary *i in images){NSString *p=[i[@"path"] lowercaseString]?:@"";BOOL hit=[p containsString:@"swift"]||[p containsString:@"libswift"];if(hit)[found addObject:@{ @"path":i[@"path"]?:@"",@"uuid":i[@"uuid"]?:@"",@"evidence":@"IMAGE_NAME_ONLY",@"metadataStatus":@"PARTIAL",@"note":@"This module does not claim complete Swift reflection or symbol extraction."}];}return @{ @"images":found,@"status":@"PARTIAL",@"limitations":@[@"Only loaded-image names are inspected.",@"Swift type metadata and reflection are not claimed."]};}
